import React from "react";
import logo from "assets/img/logo.png"; // ton logo Powered By
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import {
  faPhone,
  faEnvelope,
  faGlobe,
  faLink,
} from "@fortawesome/free-solid-svg-icons";
import {
  faFacebook,
  faLinkedin,
  faYoutube,
} from "@fortawesome/free-brands-svg-icons";

export default function Footer() {
  return (
    <footer className="bg-[#1c2b68] text-white py-12">
      <div className="container mx-auto px-6 grid grid-cols-1 md:grid-cols-3 gap-10 text-center md:text-left">

        {/* Colonne 1 */}
        <div>
          <h4 className="text-xl font-bold mb-4">Powered By</h4>
          <img src={logo} alt="Logo" className="w-20 mx-auto md:mx-0" />
        </div>

        {/* Colonne 2 */}
        <div>
          <h4 className="text-xl font-bold mb-4">Liens utiles</h4>
          <ul className="space-y-3">
            <li className="flex items-center gap-3 justify-center md:justify-start">
              <FontAwesomeIcon icon={faLink} className="text-gray-300" />
              Red Hat Enterprise Linux
            </li>
            <li className="flex items-center gap-3 justify-center md:justify-start">
              <FontAwesomeIcon icon={faLink} className="text-gray-300" />
              Openshift AI
            </li>
            <li className="flex items-center gap-3 justify-center md:justify-start">
              <FontAwesomeIcon icon={faLink} className="text-gray-300" />
              Heritage Cloud
            </li>
          </ul>
        </div>

        {/* Colonne 3 */}
        <div>
          <h4 className="text-xl font-bold mb-4">Contacts</h4>
          <ul className="space-y-3">
